#!/usr/bin/env bash
# Generated by scripts/build-clx.sh; edit bin/clx.d/* and rebuild.
# CLX — Claude Code wrapper for the Orchestrator fleet.
set -euo pipefail

# ── Constants ──────────────────────────────────────────────────
CLX_ENGINE="claude"
CLX_CLI_BINARY="claude"
CLX_WRAPPER_NAME="clx"

# ── Terminal ───────────────────────────────────────────────────
CLAUDE_TERM_IS_DUMB=0
if [[ "${TERM:-}" == "dumb" ]]; then
  CLAUDE_TERM_IS_DUMB=1
fi

CLAUDE_COLOR_ENABLED=0
if [[ -t 1 ]] && [[ -z "${NO_COLOR:-}" ]] && ((!CLAUDE_TERM_IS_DUMB)); then
  CLAUDE_COLOR_ENABLED=1
fi

if ((CLAUDE_COLOR_ENABLED)); then
  BOLD="\033[1m"
  DIM="\033[2m"
  GREEN="\033[32m"
  YELLOW="\033[33m"
  ORANGE="\033[38;5;208m"
  PINK="\033[38;5;205m"
  CYAN="\033[96m"
  BLUE="\033[36m"
  MAGENTA="\033[35m"
  VIOLET="\033[38;5;141m"
  RED="\033[31m"
  RESET="\033[0m"
else
  BOLD="" DIM="" GREEN="" YELLOW="" ORANGE="" PINK="" CYAN="" BLUE="" MAGENTA="" VIOLET="" RED="" RESET=""
fi

if ((CLAUDE_TERM_IS_DUMB)); then
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:->}"
else
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:-}"
fi
LOG_PREFIX_WARN="${LOG_PREFIX_WARN:-!}"
LOG_PREFIX_ERROR="${LOG_PREFIX_ERROR:-x}"

CLAUDE_SILENT="${CLAUDE_SILENT:-0}"
CLAUDE_DEBUG="${CLAUDE_DEBUG:-0}"

log_info() {
  ((CLAUDE_SILENT)) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${VIOLET}${BOLD}" "$LOG_PREFIX_INFO" "${RESET}" "$line"
  done <<<"$msg"
}

log_warn() {
  ((CLAUDE_SILENT)) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${YELLOW}${BOLD}" "$LOG_PREFIX_WARN" "${RESET}" "$line" >&2
  done <<<"$msg"
}

log_error() {
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${RED}${BOLD}" "$LOG_PREFIX_ERROR" "${RESET}" "$line" >&2
  done <<<"$msg"
}

log_debug() {
  ((CLAUDE_SILENT)) && return 0
  ((CLAUDE_DEBUG)) && printf "%b[debug]%b %s\n" "${DIM}" "${RESET}" "$1" >&2
  return 0
}

CLX_BOOT_START_NS=""
clx_time_ms() { date +%s%N 2>/dev/null || true; }

clx_elapsed_ms() {
  local start_ns="$1"
  local end_ns
  end_ns="$(clx_time_ms)"
  if [[ "$start_ns" =~ ^[0-9]+$ ]] && [[ "$end_ns" =~ ^[0-9]+$ ]]; then
    printf '%s' $(((end_ns - start_ns) / 1000000))
  fi
}

clx_debug_phase() {
  local label="$1"
  local start_ns="$2"
  local elapsed
  elapsed="$(clx_elapsed_ms "$start_ns")"
  if [[ -n "$elapsed" ]]; then
    log_debug "timing: ${label} ${elapsed}ms"
  fi
}

CLX_BOOT_START_NS="$(clx_time_ms)"

lowercase() {
  local input="${1-}"
  printf '%s' "$input" | tr '[:upper:]' '[:lower:]'
}

# ── ANSI / text helpers ───────────────────────────────────────
SED_ERE_FLAG=""
detect_sed_ere_flag() {
  if [[ -n "$SED_ERE_FLAG" ]]; then
    return 0
  fi
  if echo x | sed -r 's/x/x/' >/dev/null 2>&1; then
    SED_ERE_FLAG="-r"
  else
    SED_ERE_FLAG="-E"
  fi
}

strip_ansi_sgr() {
  local text="${1-}"
  detect_sed_ere_flag
  sed "$SED_ERE_FLAG" 's/\x1B\[[0-9;]*[mK]//g' <<<"$text"
}

strip_zero_width_text() {
  local text="${1-}"
  text="${text//$'\uFE0E'/}"
  text="${text//$'\uFE0F'/}"
  text="${text//$'\u200D'/}"
  printf '%s' "$text"
}

visible_text_width() {
  local text="${1-}"
  local plain
  plain="$(strip_zero_width_text "$(strip_ansi_sgr "$text")")"
  printf '%d' "${#plain}"
}

pad_visible_text_right() {
  local text="${1-}"
  local target_width="${2-0}"
  if [[ ! "$target_width" =~ ^[0-9]+$ ]]; then
    target_width=0
  fi
  local plain_width
  plain_width="$(visible_text_width "$text")"
  local padding=$((target_width - plain_width))
  ((padding < 0)) && padding=0
  printf '%s' "$text"
  if ((padding > 0)); then
    printf '%*s' "$padding" ""
  fi
  return 0
}

output_supports_unicode() {
  ((CLAUDE_TERM_IS_DUMB)) && return 1
  [[ -t 1 ]] || return 1
  local locale="${LC_ALL:-${LC_CTYPE:-${LANG:-}}}"
  [[ "$locale" =~ [Uu][Tt][Ff]-?8 ]] || return 1
  return 0
}

# ── Theme / banner ────────────────────────────────────────────
normalize_admin_theme() {
  local normalized
  normalized="$(lowercase "${1-}")"
  case "$normalized" in
    auto | light | dark)
      printf '%s' "$normalized"
      ;;
    *)
      printf 'auto'
      ;;
  esac
}

banner_color_tone() {
  printf 'orange'
}

banner_color_sequence() {
  printf '%b' "${VIOLET}${BOLD}"
}

BANNER_ART="$(
  cat <<'EOF'
 ██████╗ ██╗     ██╗  ██╗
██╔════╝ ██║     ╚██╗██╔╝
██║      ██║      ╚███╔╝
██║      ██║      ██╔██╗
╚██████╗ ███████╗██╔╝ ██╗
 ╚═════╝ ╚══════╝╚═╝  ╚═╝
EOF
)"

print_boot_banner() {
  local -a info_lines=("$@")
  local art_pad=0
  local gap="  "
  local banner_color=""
  banner_color="$(banner_color_sequence)"
  local cols="${COLUMNS:-}"
  if [[ ! "$cols" =~ ^[0-9]+$ ]] && command -v tput >/dev/null 2>&1; then
    cols="$(tput cols 2>/dev/null || true)"
  fi
  [[ "$cols" =~ ^[0-9]+$ ]] || cols=80

  local stacked=0
  ((cols < 60)) && stacked=1

  if ((!stacked)); then
    local art_line=""
    while IFS= read -r art_line; do
      local art_width=0
      art_width="$(visible_text_width "$art_line")"
      if ((art_width > art_pad)); then
        art_pad=$art_width
      fi
    done <<<"$BANNER_ART"
  fi

  local i=0
  while IFS= read -r art_line; do
    printf "%b %s" "${banner_color}" "$art_line"
    if ((!stacked)); then
      local art_len=0
      art_len="$(visible_text_width "$art_line")"
      local pad_n=$((art_pad - art_len))
      ((pad_n < 0)) && pad_n=0
      ((pad_n > 0)) && printf '%*s' "$pad_n" ""
    fi
    printf "%b" "${RESET}"
    if ((!stacked)) && [[ -n "${info_lines[i]:-}" ]]; then
      printf "%s%s" "$gap" "${info_lines[i]}"
    fi
    printf "\n"
    i=$((i + 1))
  done <<<"$BANNER_ART"

  if ((stacked)); then
    local info
    for info in "${info_lines[@]}"; do
      [[ -z "$info" ]] && continue
      printf "  %s\n" "$info"
    done
  fi
}

# ── Colorize helpers ──────────────────────────────────────────
colorize() {
  local text="$1" tone="$2"
  case "$tone" in
    green) printf "%b%s%b" "${GREEN}${BOLD}" "$text" "${RESET}" ;;
    yellow) printf "%b%s%b" "${YELLOW}${BOLD}" "$text" "${RESET}" ;;
    orange) printf "%b%s%b" "${ORANGE}${BOLD}" "$text" "${RESET}" ;;
    red) printf "%b%s%b" "${RED}${BOLD}" "$text" "${RESET}" ;;
    *) printf "%s" "$text" ;;
  esac
}

colorize_sync_status() {
  local val="$1"
  case "$val" in
    ok) colorize "$val" "green" ;;
    offline | concurrent | skip | no-python) colorize "$val" "yellow" ;;
    unknown) printf "%s" "$val" ;;
    *) colorize "$val" "red" ;;
  esac
}

# ── Summary formatting ────────────────────────────────────────
ROW_LABEL_WIDTH=12
ROW_VALUE_WIDTH=32
QUOTA_BAR_WIDTH=24
QUOTA_METRIC_LABEL_WIDTH=20
SUMMARY_ITEMS_PER_ROW=3
SUMMARY_ITEMS_PER_ROW_QUOTA=1
SUMMARY_ITEMS_PER_ROW_VERSIONS=2
SUMMARY_COLUMN_GAP=4
SUMMARY_GUTTER="  "

summary_divider() {
  local cols="${COLUMNS:-}"
  if [[ ! "$cols" =~ ^[0-9]+$ ]] && command -v tput >/dev/null 2>&1; then
    cols="$(tput cols 2>/dev/null || true)"
  fi
  if [[ ! "$cols" =~ ^[0-9]+$ ]] || ((cols < 40)); then
    cols=80
  fi
  local w=$((cols - 2))
  ((w < 20)) && w=20
  if output_supports_unicode; then
    local line=""
    local si
    for ((si = 0; si < w; si++)); do line+="─"; done
    printf "%b" "${DIM}${line}${RESET}"
  else
    printf "%b" "${DIM}$(printf '%*s' "$w" '' | tr ' ' '-')${RESET}"
  fi
}

summary_header() {
  local title="$1" tone="${2-}"
  local ts=""
  if command -v date >/dev/null 2>&1; then
    ts="$(date '+%Y-%m-%d %H:%M' 2>/dev/null || true)"
  fi
  local left
  printf -v left "%bclx%b" "$(banner_color_sequence)" "${RESET}"
  [[ -n "$ts" ]] && left+=" $(printf '%b%s%b' "${DIM}" "$ts" "${RESET}")"
  local right=""
  if [[ -n "$title" ]]; then
    if [[ -n "$tone" ]]; then
      right="$(colorize "$title" "$tone")"
    else
      printf -v right "%b%s%b" "${BOLD}" "$title" "${RESET}"
    fi
  fi
  local dot_sep
  printf -v dot_sep "%b·%b" "${DIM}" "${RESET}"
  if [[ -n "$right" ]]; then
    printf "%s  %s  %s" "$left" "$dot_sep" "$right"
  else
    printf "%s" "$left"
  fi
}

summary_row() {
  local label="$1"
  shift
  local text="$*"
  printf "%b%s%b%s%s%b" "${DIM}" "$label" "${RESET}" "${SUMMARY_GUTTER}·${SUMMARY_GUTTER}" "$text" "${RESET}"
}

format_simple_row() {
  local label="$1" text="$2"
  if [[ -t 1 ]]; then
    local cols="${COLUMNS:-}"
    if [[ ! "$cols" =~ ^[0-9]+$ ]] && command -v tput >/dev/null 2>&1; then
      cols="$(tput cols 2>/dev/null || true)"
    fi
    if [[ "$cols" =~ ^[0-9]+$ ]]; then
      local max=$((cols - ROW_LABEL_WIDTH - 5))
      if ((max >= 20)); then
        if [[ "$text" != *$'\033['* ]]; then
          if ((${#text} > max)); then
            local first=1 chunk
            while IFS= read -r chunk; do
              if ((first)); then
                printf "%-${ROW_LABEL_WIDTH}s | %s" "$label" "$chunk"
                first=0
              else
                printf "\n%-${ROW_LABEL_WIDTH}s | %s" "" "$chunk"
              fi
            done <<<"$(fold -s -w "$max" <<<"$text")"
            return
          fi
        else
          local plain
          plain="$(strip_ansi_sgr "$text")"
          if ((${#plain} > max)); then
            local out="" cur_line="" token rest="$text"
            while [[ -n "$rest" ]]; do
              if [[ "$rest" == *" "* ]]; then
                token="${rest%% *}"
                rest="${rest#* }"
              else
                token="$rest"
                rest=""
              fi
              local cand="$cur_line"
              [[ -n "$cand" ]] && cand+=" "
              cand+="$token"
              local cand_plain
              cand_plain="$(strip_ansi_sgr "$cand")"
              if ((${#cand_plain} > max)) && [[ -n "$cur_line" ]]; then
                if [[ -n "$out" ]]; then
                  printf "\n%-${ROW_LABEL_WIDTH}s | %s" "" "$cur_line"
                else
                  printf "%-${ROW_LABEL_WIDTH}s | %s" "$label" "$cur_line"
                fi
                out="x"
                cur_line="$token"
              else
                cur_line="$cand"
              fi
            done
            if [[ -n "$cur_line" ]]; then
              if [[ -n "$out" ]]; then
                printf "\n%-${ROW_LABEL_WIDTH}s | %s" "" "$cur_line"
              else
                printf "%-${ROW_LABEL_WIDTH}s | %s" "$label" "$cur_line"
              fi
            fi
            return
          fi
        fi
      fi
    fi
  fi
  printf "%-${ROW_LABEL_WIDTH}s | %s" "$label" "$text"
}

section_bullet() {
  if output_supports_unicode; then
    printf "•"
  else
    printf "-"
  fi
}

compute_row_label_width() {
  local width="$ROW_LABEL_WIDTH"
  local label=""
  local plain=""
  local plain_len=0
  for label in "$@"; do
    [[ -z "$label" ]] && continue
    plain="$(strip_ansi_sgr "$label")"
    plain_len=${#plain}
    if ((plain_len > width)); then
      width=$plain_len
    fi
  done
  printf '%s' "$width"
}

# ── Join helpers ──────────────────────────────────────────────
join_with_sep() {
  local sep="$1"
  shift
  local out="" part
  for part in "$@"; do
    [[ -z "$part" ]] && continue
    if [[ -n "$out" ]]; then
      out+="$sep"
    fi
    out+="$part"
  done
  printf "%s" "$out"
}

join_with_semicolon() {
  local out=""
  local part
  for part in "$@"; do
    [[ -z "$part" ]] && continue
    if [[ -n "$out" ]]; then
      out+="; "
    fi
    out+="$part"
  done
  printf "%s" "$out"
}

human_join() {
  local items=("$@")
  local count=${#items[@]}
  if ((count == 0)); then
    printf ''
  elif ((count == 1)); then
    printf '%s' "${items[0]}"
  elif ((count == 2)); then
    printf '%s and %s' "${items[0]}" "${items[1]}"
  else
    local last="${items[count-1]}"
    items=("${items[@]:0:count-1}")
    printf '%s, and %s' "$(printf '%s, ' "${items[@]}" | sed 's/, $//')" "$last"
  fi
}

# ── Number / time formatting ─────────────────────────────────
format_grouped_int() {
  local raw="$1"
  [[ "$raw" =~ ^-?[0-9]+$ ]] || {
    printf "%s" "$raw"
    return
  }
  local sign=""
  if [[ "$raw" == -* ]]; then
    sign="-"
    raw="${raw#-}"
  fi
  local out=""
  local len=${#raw}
  while ((len > 3)); do
    local chunk_start=$((len - 3))
    out=",${raw:chunk_start:3}${out}"
    raw="${raw:0:chunk_start}"
    len=${#raw}
  done
  printf "%s%s%s" "$sign" "$raw" "$out"
}

format_compact_number() {
  local n="$1"
  [[ "$n" =~ ^[0-9]+$ ]] || {
    printf "%s" "$n"
    return
  }
  if ((n >= 10000000)); then
    printf "%dM" $(((n + 500000) / 1000000))
  elif ((n >= 1000000)); then
    local m=$((n / 1000000))
    local frac=$(((n % 1000000 + 50000) / 100000))
    if ((frac >= 10)); then
      m=$((m + 1))
      frac=0
    fi
    if ((m >= 10)); then
      printf "%dM" "$m"
    else
      printf "%d.%dM" "$m" "$frac"
    fi
  elif ((n >= 100000)); then
    printf "%dK" $(((n + 500) / 1000))
  elif ((n >= 10000)); then
    local k=$((n / 1000))
    local frac=$(((n % 1000 + 50) / 100))
    if ((frac >= 10)); then
      k=$((k + 1))
      frac=0
    fi
    if ((k >= 100)); then
      printf "%dK" "$k"
    else
      printf "%d.%dK" "$k" "$frac"
    fi
  else
    printf "%s" "$(format_grouped_int "$n")"
  fi
}

format_duration_short() {
  local seconds="$1"
  [[ "$seconds" =~ ^[0-9]+$ ]] || {
    printf ""
    return
  }
  local s=$seconds
  local days=$((s / 86400))
  s=$((s % 86400))
  local hours=$((s / 3600))
  s=$((s % 3600))
  local mins=$((s / 60))
  local parts=()
  ((days > 0)) && parts+=("${days}d")
  ((hours > 0)) && parts+=("${hours}h")
  ((mins > 0)) && parts+=("${mins}m")
  if ((${#parts[@]} == 0)); then
    parts=("<1m")
  fi
  printf "%s" "${parts[*]}"
}

format_duration_long() {
  local seconds="$1"
  [[ "$seconds" =~ ^[0-9]+$ ]] || {
    printf ""
    return
  }
  local s=$seconds
  local days=$((s / 86400))
  s=$((s % 86400))
  local hours=$((s / 3600))
  s=$((s % 3600))
  local mins=$((s / 60))
  local parts=()
  if ((days == 1)); then
    parts+=("1 day")
  elif ((days > 1)); then parts+=("${days} days"); fi
  if ((hours == 1)); then
    parts+=("1 hour")
  elif ((hours > 1)); then parts+=("${hours} hours"); fi
  if ((${#parts[@]} == 0)); then
    if ((mins == 1)); then
      parts+=("1 minute")
    elif ((mins > 1)); then
      parts+=("${mins} minutes")
    else parts+=("<1 minute"); fi
  fi
  local IFS=", "
  printf "%s" "${parts[*]}"
}

seconds_since_iso() {
  local iso="$1"
  [[ -z "$iso" ]] && return 1
  if ! command -v python3 >/dev/null 2>&1; then
    return 1
  fi
  python3 - "$iso" <<'PY'
import datetime, sys
raw = sys.argv[1]

def parse_iso8601(value):
    normalized = (value or "").strip()
    if not normalized:
        raise ValueError("missing timestamp")
    if normalized.endswith("Z"):
        normalized = normalized[:-1] + "+0000"
    elif len(normalized) >= 6 and normalized[-6] in ("+", "-") and normalized[-3] == ":":
        normalized = normalized[:-3] + normalized[-2:]
    for fmt in ("%Y-%m-%dT%H:%M:%S.%f%z", "%Y-%m-%dT%H:%M:%S%z"):
        try:
            return datetime.datetime.strptime(normalized, fmt)
        except Exception:
            continue
    raise ValueError("invalid timestamp")

try:
    dt = parse_iso8601(raw)
except Exception:
    sys.exit(1)
now = datetime.datetime.now(datetime.timezone.utc)
delta = now - dt
print(int(delta.total_seconds()))
PY
}

format_relative_iso() {
  local iso="$1"
  local seconds=""
  seconds="$(seconds_since_iso "$iso" 2>/dev/null || true)"
  if [[ -z "$seconds" ]]; then
    return 1
  fi
  if ((seconds < 0)); then
    seconds=$((-seconds))
  fi
  local label
  label="$(format_duration_short "$seconds")"
  if [[ -z "$label" ]]; then
    return 1
  fi
  printf "%s ago" "$label"
}

extract_version_token() {
  local display="$1"
  if [[ "$display" =~ ([0-9]+[0-9A-Za-z\.\-\+_]*) ]]; then
    printf "%s" "${BASH_REMATCH[1]}"
  fi
}

# ── Status icons ──────────────────────────────────────────────
status_icon() {
  if output_supports_unicode; then
    case "$1" in
      green) printf "✅" ;;
      yellow) printf "⚠" ;;
      red) printf "⛔" ;;
      *) printf "•" ;;
    esac
  else
    case "$1" in
      green) printf "OK" ;;
      yellow) printf "WARN" ;;
      red) printf "FAIL" ;;
      *) printf "INFO" ;;
    esac
  fi
}

format_core_entry() {
  local name="$1" tone="$2" detail="${3-}" note="${4-}"
  local icon
  icon="$(status_icon "$tone")"
  local text="$name $icon"
  if [[ -n "$detail" ]]; then
    if [[ "$tone" == "green" ]]; then
      text+=" $detail"
    else
      text+=" $(colorize "$detail" "$tone")"
    fi
  elif [[ -n "$note" ]]; then
    text+=" $note"
  fi
  printf "%s" "$text"
}

format_version_entry() {
  local name="$1" tone="$2" installed="$3" target="$4" status="$5"
  local icon
  icon="$(status_icon "$tone")"
  local ver_inst
  ver_inst="$(extract_version_token "$installed")"
  local ver_target
  ver_target="$(extract_version_token "$target")"
  local text="$name"
  if [[ -n "$ver_inst" ]]; then
    text+=" ${ver_inst}"
  fi
  if [[ -n "$ver_target" && "$ver_target" != "$ver_inst" ]]; then
    text+="→${ver_target}"
  fi
  if [[ "$tone" == "green" && (-z "$ver_target" || "$ver_target" == "$ver_inst") ]]; then
    text+=" ✅"
  else
    text+=" ${icon}"
    if [[ -n "$status" ]]; then
      text+=" $(colorize "$status" "$tone")"
    fi
  fi
  printf "%s" "$text"
}

# ── Quota helpers ─────────────────────────────────────────────
build_quota_bar() {
  local pct="$1" width="$2"
  ((width < 1)) && width=24
  ((pct < 0)) && pct=0
  ((pct > 100)) && pct=100
  local filled=$(((pct * width + 50) / 100))
  ((filled > width)) && filled=$width
  local fill_color="${GREEN}${BOLD}"
  if ((pct >= 95)); then
    fill_color="${RED}${BOLD}"
  elif ((pct >= 80)); then
    fill_color="${ORANGE}${BOLD}"
  fi
  local fill_char
  local empty_char
  if output_supports_unicode; then
    fill_char="${CLX_QUOTA_FILL_CHAR:-█}"
    empty_char="${CLX_QUOTA_EMPTY_CHAR:-░}"
  else
    fill_char="${CLX_QUOTA_FILL_CHAR:-#}"
    empty_char="${CLX_QUOTA_EMPTY_CHAR:--}"
  fi
  local bar=""
  if ((filled > 0)); then
    local filled_part
    filled_part="$(printf '%*s' "$filled" "")"
    filled_part="${filled_part// /$fill_char}"
    bar+="${fill_color}${filled_part}"
  fi
  local empty_count=$((width - filled))
  if ((empty_count > 0)); then
    local empty_part
    empty_part="$(printf '%*s' "$empty_count" "")"
    empty_part="${empty_part// /$empty_char}"
    bar+="${RESET}${DIM}${empty_part}"
  fi
  bar+="${RESET}"
  printf -v bar "%b" "$bar"
  printf "%s" "$bar"
}

render_quota_line() {
  local used="$1" reset_after="$2" reset_at="$3"
  local width=${QUOTA_BAR_WIDTH:-24}
  local tone="yellow"
  local text="n/a"
  local note=""
  if [[ "$used" =~ ^[0-9]+$ ]]; then
    local pct=$used
    ((pct < 0)) && pct=0
    ((pct > 100)) && pct=100
    ((width < 1)) && width=24
    local bar
    bar="$(build_quota_bar "$pct" "$width")"
    if [[ "$reset_after" =~ ^[0-9]+$ ]]; then
      local dur
      dur=$(format_duration_short "$reset_after")
      [[ -n "$dur" ]] && note="resets in ${dur}"
    elif [[ -n "$reset_at" ]]; then
      note="resets @ ${reset_at}"
    fi
    if ((pct >= 95)); then
      tone="red"
    elif ((pct >= 80)); then
      tone="orange"
    else
      tone="green"
    fi
    text=$(printf "%3d%% [%s]" "$pct" "$bar")
  fi
  printf "%s\t%s\t%s" "$tone" "$text" "$note"
}

project_quota_usage() {
  local used_pct="$1" limit_seconds="$2" reset_after="$3"
  [[ "$used_pct" =~ ^[0-9]+$ ]] || return
  [[ "$limit_seconds" =~ ^[0-9]+$ ]] || return
  ((limit_seconds > 0)) || return
  local remaining=0
  if [[ "$reset_after" =~ ^[0-9]+$ ]]; then
    remaining="$reset_after"
  fi
  ((remaining < 0)) && remaining=0
  local elapsed=$((limit_seconds - remaining))
  ((elapsed < 1)) && return
  ((elapsed > limit_seconds)) && elapsed=limit_seconds
  local projected=$(((used_pct * limit_seconds + elapsed / 2) / elapsed))
  ((projected > 999)) && projected=999
  ((projected > 100)) && projected=100
  printf "%d" "$projected"
}

project_quota_hit_eta() {
  local used_pct="$1" limit_seconds="$2" reset_after="$3"
  [[ "$used_pct" =~ ^[0-9]+$ ]] || return
  [[ "$limit_seconds" =~ ^[0-9]+$ ]] || return
  [[ "$reset_after" =~ ^[0-9]+$ ]] || return
  ((used_pct > 0)) || return
  ((limit_seconds > 0)) || return
  local remaining="$reset_after"
  ((remaining < 0)) && remaining=0
  local elapsed=$((limit_seconds - remaining))
  ((elapsed < 1)) && return
  ((elapsed > limit_seconds)) && elapsed=limit_seconds
  local projected
  projected="$(project_quota_usage "$used_pct" "$limit_seconds" "$remaining" || true)"
  [[ "$projected" =~ ^[0-9]+$ ]] || return
  ((projected >= 100)) || return
  local target_elapsed=$(((100 * elapsed + used_pct - 1) / used_pct))
  ((target_elapsed <= elapsed)) && target_elapsed=$elapsed
  local eta=$((target_elapsed - elapsed))
  ((eta < 0)) && eta=0
  ((eta < remaining)) || return
  format_duration_long "$eta"
}

# ── Auth label formatting ─────────────────────────────────────

format_auth_label() {
  local status="$1" action="$2" msg="$3"
  if ((!HOST_IS_SECURE)) && [[ "$status" =~ ^(outdated|missing|upload_required)$ ]]; then
    local parts=("status refreshed (insecure host)")
    case "$action" in
      store | retrieve | outdated) parts+=("fetched latest auth") ;;
    esac
    [[ -n "$msg" ]] && parts+=("$msg")
    printf "%s" "$(join_with_semicolon "${parts[@]}")"
    return
  fi
  local parts=()
  case "$status" in
    valid) parts+=("status valid (matches server)") ;;
    outdated) parts+=("status outdated (server newer)") ;;
    missing) parts+=("status missing (upload needed)") ;;
    upload_required) parts+=("status upload required (client newer)") ;;
    *)
      [[ -n "$status" ]] && parts+=("status ${status}")
      ;;
  esac
  case "$action" in
    valid) parts+=("no update needed") ;;
    store) parts+=("stored latest auth on server") ;;
    retrieve) parts+=("pulled latest auth from server") ;;
    *)
      [[ -n "$action" ]] && parts+=("action ${action}")
      ;;
  esac
  [[ -n "$msg" ]] && parts+=("$msg")
  printf "%s" "$(join_with_semicolon "${parts[@]}")"
}

# ── Health dot builder ────────────────────────────────────────
build_health_dot() {
  local name="$1" tone="$2" updated="${3:-0}"
  local marker="●"
  if [[ "$updated" == "1" ]]; then
    marker="⬆️"
    output_supports_unicode || marker="^"
  else
    output_supports_unicode || marker="*"
  fi
  printf "%s %s" "$(colorize "$marker" "$tone")" "$name"
}

print_section_rows() {
  local label="$1"
  shift
  local first=1
  local items_per_row="$SUMMARY_ITEMS_PER_ROW"
  if [[ "$label" == "Quota" ]]; then
    items_per_row="${SUMMARY_ITEMS_PER_ROW_QUOTA:-1}"
  elif [[ "$label" == "Versions" ]]; then
    items_per_row="${SUMMARY_ITEMS_PER_ROW_VERSIONS:-2}"
  fi
  if [[ "${CLAUDE_SUMMARY_ITEMS_PER_ROW:-}" =~ ^[1-9][0-9]*$ ]]; then
    items_per_row="${CLAUDE_SUMMARY_ITEMS_PER_ROW}"
  fi
  local label_key
  label_key="$(printf '%s' "$label" | tr '[:lower:]' '[:upper:]' | tr -c '[:alnum:]' '_')"
  local label_items_var="CLAUDE_SUMMARY_ITEMS_PER_ROW_${label_key}"
  local label_items="${!label_items_var-}"
  if [[ "$label_items" =~ ^[1-9][0-9]*$ ]]; then
    items_per_row="$label_items"
  fi
  if [[ ! "$items_per_row" =~ ^[1-9][0-9]*$ ]]; then
    items_per_row=1
  fi

  local gap_width="${SUMMARY_COLUMN_GAP:-4}"
  if [[ ! "$gap_width" =~ ^[0-9]+$ ]]; then
    gap_width=4
  fi
  local gap
  gap="$(printf '%*s' "$gap_width" "")"

  local section_entries=()
  local line
  for line in "$@"; do
    [[ -z "$line" ]] && continue
    section_entries+=("$line")
  done
  if ((${#section_entries[@]} == 0)); then
    return 0
  fi

  local column_widths=()
  local col=0
  for ((col = 0; col < items_per_row; col++)); do
    column_widths[col]=0
  done

  local entry_index=0
  local entry=""
  local plain=""
  local plain_len=0
  for entry in "${section_entries[@]}"; do
    col=$((entry_index % items_per_row))
    plain="$(strip_ansi_sgr "$entry")"
    plain_len=${#plain}
    if ((plain_len > column_widths[col])); then
      column_widths[col]=$plain_len
    fi
    entry_index=$((entry_index + 1))
  done

  local row_text=""
  local padded_entry=""
  entry_index=0
  for entry in "${section_entries[@]}"; do
    col=$((entry_index % items_per_row))
    if ((col > 0)); then
      row_text+="$gap"
    fi
    padded_entry="$entry"
    plain="$(strip_ansi_sgr "$entry")"
    plain_len=${#plain}
    if ((plain_len < column_widths[col])); then
      padded_entry+="$(printf '%*s' "$((column_widths[col] - plain_len))" "")"
    fi
    row_text+="$padded_entry"

    entry_index=$((entry_index + 1))
    if ((entry_index % items_per_row == 0)); then
      if ((first)); then
        log_info "$(format_simple_row "$label" "$row_text")"
        first=0
      else
        log_info "$(format_simple_row "" "$row_text")"
      fi
      row_text=""
    fi
  done

  if [[ -n "$row_text" ]]; then
    if ((first)); then
      log_info "$(format_simple_row "$label" "$row_text")"
    else
      log_info "$(format_simple_row "" "$row_text")"
    fi
  fi
}

# ── Node.js detection (Claude Code requires Node.js) ──────────
detect_node() {
  local candidate
  for candidate in node nodejs; do
    if command -v "$candidate" >/dev/null 2>&1; then
      printf '%s' "$(command -v "$candidate")"
      return 0
    fi
  done
  return 1
}

CLX_NODE_BIN=""
CLX_NODE_BIN="$(detect_node || true)"

# ── Claude Code CLI detection ─────────────────────────────────
detect_claude_cli() {
  local candidate
  for candidate in claude claude-code; do
    if command -v "$candidate" >/dev/null 2>&1; then
      printf '%s' "$(command -v "$candidate")"
      return 0
    fi
  done
  # Check common npm global install paths.
  local npm_prefix=""
  if command -v npm >/dev/null 2>&1; then
    npm_prefix="$(npm prefix -g 2>/dev/null || true)"
    if [[ -n "$npm_prefix" ]] && [[ -x "$npm_prefix/bin/claude" ]]; then
      printf '%s' "$npm_prefix/bin/claude"
      return 0
    fi
  fi
  return 1
}

