# ── curl helper ────────────────────────────────────────────────
clx_curl() {
  local curl_args=(curl -fsSL --max-time 30)
  if [[ -n "$CLAUDE_SYNC_CA_FILE" ]] && [[ -f "$CLAUDE_SYNC_CA_FILE" ]]; then
    curl_args+=(--cacert "$CLAUDE_SYNC_CA_FILE")
  fi
  if [[ "$CLAUDE_SYNC_ALLOW_INSECURE" == "1" ]]; then
    curl_args+=(-k)
  fi
  curl_args+=(
    -H "Authorization: Bearer ${CLAUDE_SYNC_API_KEY}"
    -H "X-Engine: claude"
    -H "User-Agent: clx/${WRAPPER_VERSION}"
  )
  "${curl_args[@]}" "$@"
}
